package Level_1;
import java.util.*;
public class User_Enters_0 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner sc = new Scanner(System.in);
		int n ;
		n = sc.nextInt();
		double total =n;
		while(n!=0) {
			n = sc.nextInt();
			total+=n;
			
		}
		System.out.println(total);
	}

}
